def exponent(a, y, m):
	if y == 0:
		return 1
	ss = y // 2
	an = exponent(a, ss, m)
	an = an * an % m
	if y % 2 == 0:
		return an
	else:
		return a * an % m
import bisect
(n, q) = map(int, input().split())
it = list(map(int, input().split()))
a = [1]
x = 10 ** 9 + 7
for i in range(1, n + 1):
	a.append(a[-1] * (i + 1) % x)
ind = {}
freq = {}
mult = [[] for i in range(n)]
ii = 0
for (j, i) in enumerate(it):
	try:
		freq[i].append(j)
		if len(freq[i]) == 2:
			ind[i] = ii
			ii += 1
			mult[ind[i]].append(freq[i][0])
		try:
			mult[ind[i]].append(j)
		except:
			pass
	except:
		freq[i] = [j]
ans = 0
dp = {}
for _ in range(q):
	(l1, l2, r1, r2) = map(int, input().split())
	l = (l1 * ans + l2) % n
	r = (r1 * ans + r2) % n
	(l, r) = sorted([l, r])
	ans = a[r - l]
	for ii in ind:
		ii = mult[ind[ii]]
		if ii[0] > r:
			break
		if ii[-1] < l:
			continue
		ij = bisect.bisect_left(ii, l)
		ji = bisect.bisect_right(ii, r)
		if ji > ij + 1:
			try:
				ans = ans * dp[ji - ij - 1]
			except:
				dp[ji - ij - 1] = exponent(a[ji - ij - 1], x - 2, x)
				ans = ans * dp[ji - ij - 1]
			ans = ans % x
	print(ans % x)
